		return m.handleTick()

	case spinner.TickMsg:
		if m.checking {
			m.spinner, cmd = m.spinner.Update(msg)
			cmds = append(cmds, cmd)
		}

	case CheckCompleteMsg:
		return m.handleCheckComplete(msg)

