// resize lays the table and the form out. The table takes the full viewport
// width, borders included (Rule 116).
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height
	m.table.Resize(width, max(height-1, 1))
	if m.form != nil {
		m.form.SetWidth(width)
	}
}

func (m Model) handleCatalogLoaded(msg CatalogLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [templates] opening the catalog: %v", msg.Err)
		m.storeErr = msg.Err
		return m, tea.Batch(
			m.footer.Error("Could not read the template catalog — check logs"),
			m.refusePendingRequests(reasonUnreadable),
		)
	}
	m.store = msg.Store
	m.storeErr = nil
	m.declared = msg.Store.List()
	m.rebuild()
	replay := m.drainPendingRequests()
	if problems := msg.Store.Problems(); len(problems) > 0 {
		for _, err := range problems {
			log.Printf("ERROR [templates] catalog entry skipped: %v", err)
		}
		return m, tea.Batch(m.refreshSynced(), replay, m.footer.Warn(fmt.Sprintf("%d catalog %s skipped — check logs", len(problems), plural(len(problems)))))
	}
	return m, tea.Batch(m.refreshSynced(), replay)
}

// refreshSynced re-reads the age of every copy. It follows whatever changes it:
// the catalog (a source edited no longer matches its copy, an entry removed has
// none) and a sync or a scan (which is what makes a copy).
func (m Model) refreshSynced() tea.Cmd { return loadSyncedCmd(m.cache, m.declared) }

// plural is "entry" or "entries" for n.
func plural(n int) string {
	if n == 1 {
		return "entry"
	}
	return "entries"
