	m.storeErr = nil
	m.declared = msg.Store.List()
	m.rebuild()
	replay := m.drainPendingRequests()
	if problems := msg.Store.Problems(); len(problems) > 0 {
		for _, err := range problems {
			log.Printf("ERROR [templates] catalog entry skipped: %v", err)
		}
