// DEVDESK-201 D3: a paste reaches the text field of the current wizard step,
// newlines become spaces, and nothing advances or goes back (Rule 111). Pasting
// into the URL field counts as touching it, like typing does.
func TestPasteReachesTheFocusedStepField(t *testing.T) {
	tests := []struct {
		name  string
		step  int
		paste string
		want  string
		read  func(m Model) string
	}{
		{"context name", stepContextName, "staging", "staging", func(m Model) string { return m.contextNameInput.Value() }},
		{"context name, multi-line", stepContextName, "a\nb", "a b", func(m Model) string { return m.contextNameInput.Value() }},
		{"context name, action letters", stepContextName, "Dq?:", "Dq?:", func(m Model) string { return m.contextNameInput.Value() }},
		{"forge URL", stepForgeURL, "https://git.internal", "https://git.internal", func(m Model) string { return m.forgeURLInput.Value() }},
		{"forge URL, multi-line", stepForgeURL, "a\nb", "a b", func(m Model) string { return m.forgeURLInput.Value() }},
		{"namespace", stepForgeNamespace, "team/sub", "team/sub", func(m Model) string { return m.forgeNamespaceInput.Value() }},
		{"token", stepForgeToken, "glpat-abc", "glpat-abc", func(m Model) string { return m.forgeTokenInput.Value() }},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			isolateHome(t)
			m := past(t, New(), "")
			m.step = tc.step
			m.updateFocus()
			m.contextNameInput.SetValue("")
			m.forgeURLInput.SetValue("")
			m.forgeURLTouched = false

			m = feed(t, m, testutil.Paste(tc.paste))

			if got := tc.read(m); got != tc.want {
				t.Errorf("field = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			if m.step != tc.step {
				t.Errorf("step = %d after the paste, want %d", m.step, tc.step)
			}
			if tc.step == stepForgeURL && !m.forgeURLTouched {
				t.Error("pasting into the URL did not mark it as touched")
			}
		})
	}
}
		forgeTokenInput:     tokenInput,
		spinner:             s,
	}
	m.forgeURLInput.SetValue(forge.VocabularyFor(config.ForgeTypes()[m.forgeTypeIdx]).ExampleURL)
	return m
}

// Init starts the cursor blink, the only thing the wizard needs on launch.
func (m Model) Init() tea.Cmd {
	return textinput.Blink
}

// Update is the single Elm-architecture entry point (Rule 110): every field
// mutation happens here, never inside a Cmd.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case spinner.TickMsg:
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		return m, cmd

	case components.ConfirmModalYesMsg:
		return m.handleConfirmYes()

	case components.ConfirmModalNoMsg:
		return m.handleConfirmNo()

	case ContextExistsMsg:
		return m.handleContextExists(msg)

	case RemoteThemesFetchedMsg:
		return m.handleRemoteThemesFetched(msg)

	case SecretBackendCheckedMsg:
		return m.handleSecretBackendChecked(msg)

	case ContainerEngineCheckedMsg:
		return m.handleContainerEngineChecked(msg)

	case TokenValidatedMsg:
		return m.handleTokenValidated(msg)

	case ContextSavedMsg:
		return m.handleContextSaved(msg)

	case CurrentContextSetMsg:
		return m.handleCurrentContextSet(msg)
	}

	if m.footer.Handle(msg) {
		return m, nil
	}
	return m, nil
}

func (m Model) handleKeyMsg(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	if m.stage == stageConfirmOverwrite || m.stage == stageConfirmSetCurrent {
		var cmd tea.Cmd
		m.confirmModal, cmd = m.confirmModal.Update(msg)
		return m, cmd
	}
	if m.stage == stageDone {
		if msg.String() == "enter" || msg.String() == "esc" || msg.String() == "q" {
			return m, tea.Quit
		}
		return m, nil
	}

	switch msg.String() {
	case "ctrl+c":
		return m, tea.Quit
	case "esc":
		return m.stepBack()
	case "left":
		return m, m.cycle(-1)
	case "right":
		return m, m.cycle(1)
	case "enter":
		return m.advance()
	}

	return m.updateFocusedInput(msg)
}

// stepBack goes to the previous question, or quits from the first one —
// there is nothing before it to go back to (Rule 111: Esc cancels or returns
// to the parent level).
func (m Model) stepBack() (tea.Model, tea.Cmd) {
	if m.step == stepFontCheck {
		return m, tea.Quit
	}
	m.step--
	m.updateFocus()

